ype {kSingleAction, kBeginAction, kEndAction};enum { kDefaultUndoStackDepth = 25 };//----------------------------------------------------------------------------------------// CLASS CUndoAction//----------------------------------------------------------------------------------------class EXPORT_MA CUndoAction{  public:	CUndoAction(TCommand* command = NULL, EActionType actionType = kSingleAction, CommandNumber id = cNoCommand);		// Constructor	CUndoAction(const CUndoAction& rhs);		// Copy Constructor					~CUndoAction() { }		// destructor		void DeleteCommand();		CUndoAction& operator=(const CUndoAction& rhs);		// assignment operator					//------------------------------------------------------------------------------------	// Methods	//------------------------------------------------------------------------------------	bool IsDone();	TCommand* GetCommand() const { return fCommand; }	CommandNumber GetCommandNumber() const { return fID; }	EActionType GetActionType() const { return fActionType; }		void SetCommand(TCommand* inCommand) { fCommand = inCommand; }	void SetCommandNumber(CommandNumber inID) { fID = inID; }	void SetActionType(EActionType inActionType) { fActionType = inActionType; }	Size TotalSize(bool justLocked) const;		// Returns the total number of bytes managed (or only locked		// handles if justLocked is true). 	Size Purge(Size needed);		// Make memory available by unloading the stack. Returns 		// the actual amount of memory purged. 	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------protected:	TCommand*		fCommand;	CommandNumber	fID;	EActionType		fActionType;};//----------------------------------------------------------------------------------------// CLASS TActionStack//----------------------------------------------------------------------------------------EXPORT_CLASS_MA(TemplateSortedArray_AC<CUndoAction>)EXPORT_CLASS_MA(TemplateArray_AC<CUndoAction>)EXPORT_CLASS_MA(TemplateArrayIterator_AC<CUndoAction>)class EXPORT_MA TActionStack : public TemplateArray_AC<CUndoAction>#if !qMSWindows							, public MPurgeable#endif{  public:	TActionStack();					virtual ~TActionStack() { }		// destructor		//------------------------------------------------------------------------------------	// Methods	//------------------------------------------------------------------------------------	CUndoAction* Top();		void PushAction(const CUndoAction& action);	void Delete(CUndoAction* action);		// finds and deletes the action	void FreeAll();		// Delete and free all the actions in the stack.		void ClearTransactions(ArrayIndex_AC count);		// Delete and free the first 'count' transactions in the stack. ClearTransactions 		// deletes complete transactions. More than 'count' actions may be deleted. 		ArrayIndex_AC CountTransactions();		// Count the number of transactions in the stack. 	ArrayIndex_AC Contains(TCommand* command);		// Find an action containing a command. Always returns 0 for NULL commands. 	bool RemoveCommandAction(TCommand* command);		// The command went away so remove actions until we get it. 	//------------------------------------------------------------------------------------	// Purging	//------------------------------------------------------------------------------------	virtual Size TotalSize(bool justLocked) const;		// Returns the total number of bytes managed (or only locked		// handles if justLocked is true). 	virtual Size Purge(Size needed);		// Make memory available by unloading the stack. Returns 		// the actual amount of memory purged. };//----------------------------------------------------------------------------------------// CLASS CActionIterator//----------------------------------------------------------------------------------------class EXPORT_MA CActionIterator : public TActionStack::Iterator{  public:  	typedef TActionStack::Iterator BaseIterator;		CActionIterator(const TActionStack* inList,					ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,					bool inForward = kIterateForward_AC);	CActionIterator(const TActionStack* inList, bool inForward = kIterateForward_AC);	// Required functions 	CUndoAction* First();	CUndoAction* Current() const { return BaseIterator::Current(); }	CUndoAction* Next();	// Convenience functions for C++meisters	CUndoAction* operator++() { return Next(); }	CUndoAction* operator++(int) { CUndoAction* returnVal = Current(); Next(); return returnVal; }	operator CUndoAction*() const { return Current(); }	CUndoAction* operator->() const { return Current(); } // this is only valid for non NULL	CUndoAction& operator*() const { return *Current(); } // this is only valid for non NULL	// Transaction level functions	long GetLevel() const { return fLevel; }  protected:	void ActionLevel();  protected:	long		fLevel;		// The current transaction level. Zero means not in a transaction. };//----------------------------------------------------------------------------------------// CLASS TUndoHandler//----------------------------------------------------------------------------------------class EXPORT_MA TUndoHandler : public TBehavior#if !qMSWindows							, public MPurgeable#endif// The TUndoHandler class provides an implementation of multiple-level// undo and redo. MacApp creates an undo handler object for each context// (typically a document or a documentless window). //   The undo handler maintains two action stacks (see class TActionStack):// one stack of actions that can be undone and one stack of actions// that can be redone.//   When undoing and redoing commands, the undo handler// processes commands in the chronological order in which commands// were performed. When the undo handler undoes and redoes commands,// only the currently active context is affected.//    MacApp sets up actions and transactions. The MacApp drag-and-drop// implementation calls the undo handler's BeginAction and EndAction// methods when tracking a drag operation. MacApp does this to ensure// that multiple drag-and-drop commands are handled as a single// transaction. MacApp automatically adds an action to the undo// stack for each command as it is posted.//    The state of the Undo and Redo menu items is maintained by// the global dispatcher (gDispatcher). When menus are set up, the// dispatcher calls the undo handler to determine whether there// are any actions in either the undo stack or the redo stack. In// addition, the dispatcher calls the undo handler to retrieve the// text for the Undo and Redo menu items.//    Undo and Redo are performed by commands that are created by// the global dispatcher. The Undo and Redo commands call the undo// handler. For the Undo command, the undo handler pops a transaction's// worth of commands from the undo stack, undoing each one and pushing// it onto the redo stack. For the Redo command, the undo handler// does the reverse.//    When undoing or redoing a command, the undo handler targets// the command's context (a command handler such as a view, a window,// or a document) by calling the command's PrepareForUndoRedo method.// Then, the undo handler calls the command's RevealUndoRedo method// to bring the context to the front and scroll it into view.//    When a document is saved or a window is closed, the undo handler// strips all actions from its associated undo stack.{  public:	//------------------------------------------------------------------------------------	// Initializer, I<Method> and Free.	//------------------------------------------------------------------------------------	TUndoHandler();					virtual ~TUndoHandler();		//------------------------------------------------------------------------------------	// Behavior	//------------------------------------------------------------------------------------	virtual void DoSetupMenus(); // override		// Setup the undo and redo menu commands. 	virtual void DoMenuCommand(CommandNumber aCommandNumber); // override		// Do the undo and redo menu commands. #if qAppleEventAware	virtual bool DoScriptCommand(CommandNumber aCommandNumber,								 TAppleEvent* message,								 TAppleEvent* reply); // override		// Do the undo and redo Apple Events. #endif	bool UndoRedoInContext(CommandNumber aCommandNumber);		// Do a undo or redo Apple Event synchronously. 	//------------------------------------------------------------------------------------	// Action History Manipulation	//------------------------------------------------------------------------------------	void AddActionToHistory(TCommand* command, CommandNumber id);		// Add an action to the list of commands that could be undone. 		// Also, clears the redo history. 		void BeginAction(CommandNumber inCommand = cNoCommand);		// Begin grouping actions together 		void EndAction(CommandNumber inCommand = cNoCommand);		// End grouping actions together. 		void ClearActionHistory();		// Clear the undo and redo stacks. 	bool Contains(TCommand* command);		// Returns whether the undo or redo stack contains a particular command. 		// Always returns false if the command is NULL. 	void Abort();		// Abort the top (trans)action in the undo stack. 		// Deletes all the commands in the transaction. 	static ArrayIndex_AC GetMaxDesiredItems() { return fgMaxDesiredItems; }		// returns the max number of undoable items to track	static ArrayIndex_AC SetMaxDesiredItems(ArrayIndex_AC newDepth);		// set the max number of undoable items to track.		// returns the previous setting.	void RemoveCommandAction(TCommand* command);		// The command went away so remove actions until we get it. 	//------------------------------------------------------------------------------------	// Do	//------------------------------------------------------------------------------------	void AboutToDo(TCommand* command);		// Purge the undo stack so there will be room for a command. 		//------------------------------------------------------------------------------------	// Undo	//------------------------------------------------------------------------------------	void Undo();		// Undo the top (trans)action in the undo stack. 		CommandNumber GetUndoID();		// Get the ID for the undo menu item for a command. 		// Returns cNoCommand if no matching command is found		//------------------------------------------------------------------------------------	// Redo	//------------------------------------------------------------------------------------	void Redo();		// Redo the top (trans)action in the redo stack. 		CommandNumber GetRedoID();		// Get the ID for the redo menu item for a command. 		// Returns cNoCommand if no matching command is found		//------------------------------------------------------------------------------------	// Purging	//------------------------------------------------------------------------------------	virtual Size TotalSize(bool justLocked) const;		// Returns the total number of bytes managed (or only locked		// handles if justLocked is true). 	virtual Size Purge(Size needed);		// Unload as much of the undo and redo stack as needed.	//------------------------------------------------------------------------------------	// Undo Handler List	//------------------------------------------------------------------------------------	static TUndoHandler* FirstUndoHandler()	{ return fgFirstUndoHandler; }		// Get the next undo handler. 	TUndoHandler* NextUndoHandler() const	{ return fNextUndoHandler; }		// Get the next undo handler. 	void InsertLast();		// Insert the undo handler at the tail of the list. 	void Remove();		// Remove the undo handler from the list. 	//------------------------------------------------------------------------------------	// For internal use only	//------------------------------------------------------------------------------------  protected:	EActionType AbortAction();		// Abort the top action in the undo stack. 		void AbortCommand(TCommand* command);		// Abort an individual command. 		EActionType UndoAction();		// Undo the top action in the undo stack. 		void UndoCommand(TCommand* command);		// Undo a command. 		EActionType RedoAction();		// Redo the top action in the undo stack. 		void RedoCommand(TCommand* command);		// Redo a command. 	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------  protected:	TActionStack		fUndoStack;				// Stack of commands that could be undone. 	TActionStack		fRedoStack;				// Stack of commands that could be redone. 	long				fInTransaction;			// Keep track of transaction level in case												// we need to abort. 	enum EActionState {kInSingleAction, kInBeginAction, kInCollectActions};	EActionState		fActionState;			// track begin/end action calls	CommandNumber		fActionCommand;			// if !cNoCommand: identifies a commandNumber that												// should be stamped on the ID of all commands												// grouped in a single action.	TUndoHandler*		fNextUndoHandler;		// Link to next undo handler. 	//------------------------------------------------------------------------------------	// static data members	//------------------------------------------------------------------------------------	static TUndoHandler*	fgFirstUndoHandler;	// Undo handler list head. 	static TUndoHandler*	fgLastUndoHandler;	// Undo handler list tail. 	// We need to better tune the following number.  This number indicates what we would like	// to be the maximum number of stacked undoable actions at any one time.  If your commands	// retain large amounts of data for performing undo/redo then you may want to reduce this	// limit.  If they are smaller then perhaps the number could be increased.  We should also	// consider having a maximum memory usage setpoint as well but the overhead of keeping	// a running total is too costly right now.	static ArrayIndex_AC	fgMaxDesiredItems;	// Maximum number of entries in stack.};//----------------------------------------------------------------------------------------// CLASS TUndoRedoCommand//----------------------------------------------------------------------------------------class EXPORT_MA TUndoRedoCommand : public TCommand// TUndoRedoCommand is a specialized subclass of TCommand that handles// the undoing and redoing of the last command of a given context.//    You seldom need to call or override the methods of this class.{  public:		TUndoRedoCommand(CommandNumber itsCommandNumber, TUndoHandler* undoHandler);		// Constructor	virtual ~TUndoRedoCommand();		// Destructor			#if qAppleEventAware	virtual TAppleEvent* MakeAppleEvent();		// Create a Undo or Redo Apple Event. #endif	bool IsUndo();		// Figures out whether we're undoing or redoing the last command. 	virtual void DoIt();		// Calls fHandler->Undo/Redo as necessary  protected:	TUndoHandler*	fHandler;};#if !qMSWindows//----------------------------------------------------------------------------------------// CLASS CUndoStackHook//----------------------------------------------------------------------------------------// A class for unloading portions of the undo stack when memory is needed.class EXPORT_MA CUndoStackHook : public CGrowZoneHook// The CUndoStackHook class is internal to MacApp.{  public:	CUndoStackHook() { }	virtual ~CUndoStackHook() { }	virtual Size TotalSize(bool justLocked) const;		// Returns the total number of bytes managed (or only locked		// handles if justLocked is true). 	virtual Size Purge(Size needed);		// Make memory available by unloading the undo stack. Returns 		// the actual amount of memory purged. };#endif // !qMSWindows//========================================================================================// GLOBAL Variables//========================================================================================#if !qMSWindowsEXPORT_MA extern CUndoStackHook gUndoStackHook;#endif//========================================================================================// GLOBAL Procedures//========================================================================================EXPORT_MA CString_AC GetUndoRedoText(bool cmdDone, CommandNumber aCommandNumber);	// Get the text for the undo or redo menu item for a command. 	#endif // __UUNDO__/*	Historical Change Record:		----- R11 -----		06/26/96	Changed nil back to NULL.		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/13/96	Fix bug in grouped commands where the source and target commands were not							separately identified when using !qUseODUndoStyle		05/10/96	Filter the removal of undo actions by the context of their related commands.		04/26/96	Fix bug where the command being executed would fail and cause the undo							handler to crash or substitute the wrong error code to the user.		----- R10 -----		03/26/96	Added CUndoStackHook and grow zone space handling.		12/15/95	Initial version. */